package egress

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"errors"
	"fmt"
	"math/big"
	"net"
	"strings"
	"sync"
	"time"
)

// CA is the per-runner MITM certificate authority (CONTRACTS.md section 2, row "Runner TLS trust"; D-11 item 7). It
// is generated by the gateway, lives only in memory, is name-constrained to the session allowlist and is valid for
// the session only. Only its certificate leaves the gateway (as the runner caPem); its key never does, and no code
// path accepts a CA or a key from a peer.
type CA struct {
	cert    *x509.Certificate
	certPEM string
	key     *ecdsa.PrivateKey
	hosts   map[string]bool

	mu     sync.Mutex
	leaves map[string]*tls.Certificate
}

// caBackdate absorbs a small clock skew between the gateway and the runner.
const caBackdate = 5 * time.Minute

// NewCA generates a CA for one session. allowed are the allowlisted hosts (lowercase); notAfter is the session end.
func NewCA(sessionID string, allowed []string, notAfter time.Time) (*CA, error) {
	if len(allowed) == 0 {
		return nil, errors.New("egress: a CA needs at least one allowed host")
	}
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, err
	}
	serial, err := randomSerial()
	if err != nil {
		return nil, err
	}
	hosts := map[string]bool{}
	var dns []string
	var ips []*net.IPNet
	for _, h := range allowed {
		h = strings.ToLower(strings.TrimSuffix(h, "."))
		hosts[h] = true
		if ip := net.ParseIP(h); ip != nil {
			bits := 8 * len(ip.To16())
			if v4 := ip.To4(); v4 != nil {
				ip, bits = v4, 32
			}
			ips = append(ips, &net.IPNet{IP: ip, Mask: net.CIDRMask(bits, bits)})
			continue
		}
		dns = append(dns, h)
	}
	now := time.Now()
	tmpl := &x509.Certificate{
		SerialNumber:                serial,
		Subject:                     pkix.Name{CommonName: "Infisical Web App session " + shortSession(sessionID), Organization: []string{"Infisical Gateway"}},
		NotBefore:                   now.Add(-caBackdate),
		NotAfter:                    notAfter,
		KeyUsage:                    x509.KeyUsageCertSign | x509.KeyUsageCRLSign,
		BasicConstraintsValid:       true,
		IsCA:                        true,
		MaxPathLen:                  0,
		MaxPathLenZero:              true,
		PermittedDNSDomainsCritical: true,
		PermittedDNSDomains:         dns,
		PermittedIPRanges:           ips,
	}
	if len(ips) == 0 {
		// No IP host is allowed: exclude every address so an IP SAN can never chain to this CA.
		tmpl.ExcludedIPRanges = []*net.IPNet{
			{IP: net.IPv4zero.To4(), Mask: net.CIDRMask(0, 32)},
			{IP: net.IPv6zero, Mask: net.CIDRMask(0, 128)},
		}
	}
	if len(dns) == 0 {
		// Only IP hosts: permit only the reserved "invalid" TLD (RFC 6761) so no real DNS name chains either.
		tmpl.PermittedDNSDomains = []string{"invalid"}
	}
	if !notAfter.After(now) {
		return nil, fmt.Errorf("egress: CA notAfter %s is in the past", notAfter.UTC().Format(time.RFC3339))
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
	if err != nil {
		return nil, fmt.Errorf("egress: create CA: %w", err)
	}
	cert, err := x509.ParseCertificate(der)
	if err != nil {
		return nil, err
	}
	return &CA{
		cert: cert, key: key, hosts: hosts, leaves: map[string]*tls.Certificate{},
		certPEM: string(pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der})),
	}, nil
}

// CertPEM is the CA certificate (no key) handed to the supervisor as the runner caPem.
func (c *CA) CertPEM() string { return c.certPEM }

// Certificate is the parsed CA certificate.
func (c *CA) Certificate() *x509.Certificate { return c.cert }

// Leaf returns the serving certificate for host. The leaf carries host as its single SAN (spike F4: a broader leaf
// fails in Chromium with net_error -207) and is cached per host for the session.
func (c *CA) Leaf(host string) (*tls.Certificate, error) {
	host = strings.ToLower(strings.TrimSuffix(host, "."))
	if !c.hosts[host] {
		return nil, fmt.Errorf("egress: no leaf for %q: not in the allowlist", host)
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if l := c.leaves[host]; l != nil {
		return l, nil
	}
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, err
	}
	serial, err := randomSerial()
	if err != nil {
		return nil, err
	}
	tmpl := &x509.Certificate{
		SerialNumber: serial,
		Subject:      pkix.Name{CommonName: host},
		NotBefore:    c.cert.NotBefore,
		NotAfter:     c.cert.NotAfter,
		KeyUsage:     x509.KeyUsageDigitalSignature,
		ExtKeyUsage:  []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
	}
	if ip := net.ParseIP(host); ip != nil {
		tmpl.IPAddresses = []net.IP{ip}
	} else {
		tmpl.DNSNames = []string{host}
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, c.cert, &key.PublicKey, c.key)
	if err != nil {
		return nil, fmt.Errorf("egress: create leaf for %q: %w", host, err)
	}
	leaf := &tls.Certificate{Certificate: [][]byte{der, c.cert.Raw}, PrivateKey: key}
	c.leaves[host] = leaf
	return leaf, nil
}

func randomSerial() (*big.Int, error) {
	return rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 128))
}

func shortSession(id string) string {
	if len(id) > 12 {
		return id[:12]
	}
	return id
}
